package fileserve

import (
	"os"
	"path/filepath"
	"testing"
)

func TestTraversalEscapesRoot(t *testing.T) {
	base := t.TempDir()
	root := filepath.Join(base, "public")
	if err := os.Mkdir(root, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(base, "secret.txt"), []byte("TOP-SECRET"), 0o600); err != nil {
		t.Fatal(err)
	}
	data, err := Read(root, "../secret.txt")
	if err == nil {
		t.Fatalf("path traversal: read %q from outside the document root", data)
	}
}
